INSERT INTO m227_art VALUES
(0,0,$m227$الديباجة$m227$,$m227$قرار مجلس الوزراء رقم 1699 لسنة 2020 بتاريخ 27/08/2020 يعمل بأحكام اللائحة التنفيذية المرافقة فى شأن قانون مكافحة جرائم تقنية المعلومات المشار إليه.$m227$,'38ec81e60134b50a4da7150b9b843d8b'),
(1,-1,$m227$المادة الأولى إصدار$m227$,$m227$يعمل بأحكام اللائحة التنفيذية المرافقة فى شأن قانون مكافحة جرائم تقنية المعلومات المشار إليه.$m227$,'4734ccb322444a1d04457a0cd86a288f'),
(2,-1,$m227$المادة الثانية إصدار$m227$,$m227$ينشر هذا القرار فى الجريدة الرسمية، ويعمل به من اليوم التالى لتاريخ نشره.
صدر برئاسة مجلس الوزراء فى 8 المحرم سنة 1442 ه (الموافق 27 أغسطس سنة 2020 م).
رئيس مجلس الوزراء دكتور /مصطفى كمال مدبولى$m227$,'2532a56fde2d1261b07a2f771e5e56ac'),
(1,0,$m227$المادة 1$m227$,$m227$فى تطبيق أحكام هذه اللائحة يقصد بالكلمات والعبارات التالية المعنى المبين قرين كل منها:
الجهاز: الجهاز القومى لتنظيم الاتصالات.
التشفير: Encryption منظومة تقنية حسابية تستخدم مفاتيح خاصة لمعالجة وتحويل البيانات والمعلومات المقروءة إلكترونيا بحيث تمنع استخلاص هذه البيانات والمعلومات إلا عن طريق استخدام مفتاح أو مفاتيح فك الشفرة.
مفتاح التشفير: Encryption Key أرقام أو رموز أو حروف ذات طول محدد تستخدم فى عمليات التشفير وفك التشفير.
ويستخدم نفس المفتاح فى التشفير وفك التشفير ويسمى التشفير المتماثل، ويجب الحفاظ على سرية المفتاح.
ويستخدم زوج من المفاتيح مترابطين بعلاقة رياضية بحيث يستخدم أحدهما فى التشفير والآخر فى فك التشفير ويسمى التشفير غير المتماثل، ويجب الحفاظ على سرية أحد المفاتيح بينما يعلن عن الآخر بشروط ومعايير محددة.
البنية التحتية المعلوماتية الحرجة: Critical Information Infrastructure مجموعة أنظمة أو شبكات أو أصول معلوماتية أساسية يؤدى الكشف عن تفصيلاتها تعطيلها أو تغيير طريقة عملها بطريقة غير مشروعة، أو الدخول غير المصرح به عليها، أو الدخول أو الوصول بشكل غير قانونى للبيانات والمعلومات التى تحفظها أو تعالجها، أو يؤدى القيام بأى فعل غير مشروع آخر بها إلى التأثير على توافر خدمات الدولة ومرافقها الأساسية أو خسائر اقتصادية أو اجتماعية كبيرة على المستوى الوطنى.
ويعد من البنية التحتية المعلوماتية الحرجة على الأخص ما يستخدم فى الطاقة الكهربائية، الغاز الطبيعى والبترول، الاتصالات، والجهات المالية والبنوك، والصناعات المختلفة، والنقل والمواصلات والطيران المدنى، والتعليم والبحث العلمى، والبث الإذاعى والتليفزيونى، ومحطات مياه الشرب والصرف الصحى والموارد المائية، والصحة، الخدمات الحكومية وخدمات الإغاثة وخدمات الطوارئ، وغيرها من مرافق المعلومات والاتصالات التى قد تؤثر على الأمن القومى أو الاقتصاد القومى والمصلحة العامة وما فى حكمها.
نظام التحكم الصناعى: حاسب أو مجموعة حواسب متصلة ببعضها البعض، وبالمعدات المتحكم بها وأدوات الاتصال المتبادل بينهم رقمية Digital أو تناظرية، Analog أو غيرها بما فى ذلك الحساسات والمنفذات Actuator لتشغيل هذه المعدات والتحكم بها منطقيا طبقا للصناعة المعنية، أو الأعمال المطلوبة فى مكان واحد أو موزعة فى أماكن متقاربة أو موزعة جغرافيا مع اتصال النظام بالإنترنت أو بغيره من الأنظمة المماثلة أو غير المماثلة أو استقلاله وعدم اتصاله بما عداه مع تراكم مستوى التحكم أو عدم تراكمه.
نقاط الضعف: Vulnerabilities خلل أو ثغرة فى نظام تشغيل أو تطبيقات أو شبكات المعلومات أو العمليات أو السياسات الخاصة بتأمين المعلومات أو فى بيئة تقنية المعلومات أو الاتصالات والتى يمكن استغلالها فى عمليات الاختراق أو الهجوم أو الاتلاف أو التجسس أو أى عمل غير مشروع.$m227$,'4635119cde09d02a3667b22cb3909f41'),
(2,0,$m227$المادة 2$m227$,$m227$يلتزم مقدمو خدمات تقنيات المعلومات باتخاذ الإجراءات التقنية والتنظيمية التالية تنفيذا للبندين (2 و3) من الفقرة أولا من المادة رقم (2) من القانون:
1 - تشفير البيانات والمعلومات بما يحافظ على سريتها، وعدم اختراقها باستخدام نظام تشفير قياسى متماثل أو غير متماثل لا يقل فى تأمينه عن (ASE-128) Advanced Encryption Standard بمفتاح شفرة لا يقل عن (128 بت)، مع مسئوليته بالحفاظ على سرية وأمان مفتاح التشفير.
2 - تنصيب واستخدام نظم وبرامج ومعدات مكافحة البرمجيات والهجمات الخبيثة والتأكد من صلاحيتها وتحديثها.
3 - استخدام بروتوكولات آمنة، مثل بروتوكول نقل النص التشعبى المؤمن HTTPS.
4 - وضع صلاحيات بالشبكات والملفات وقواعد البيانات وتحديد المسئولين، لضمان حماية الوصول المنطقى Logical Access إلى الأصول المعلوماتية والتقنية لمنع الوصول غير المصرح به.
5 - إعداد قائمة بالأجهزة والمعدات وأرقامها المميزة والمسلسلة وطرازاتها وكذا بيان بالنظم والبرامج والتطبيقات وقواعد البيانات المستخدمة ومواصفاتها.
6 - تطبيق أفضل الممارسات والضوابط عند اختيار مواصفات كلمات السر أو المرور وفقا للملحق رقم (1) المرفق باللائحة التنفيذية.
7 - توثيق إجراءات التنصيب والتشغيل الخاصة بالأنظمة.
8 - ضمان تنفيذ وتشغيل وصيانة الأنظمة وإلزام الأطراف المتعاقد معها بإبرام اتفاقيات تحدد مستوى تقديم الخدمة مع الجهة وحدود مسئولية كل جهة.
9 - إجراء التحديثات الخاصة بالنظم والبرامج والتطبيقات بشكل دورى وإتمام الاختبارات اللازمة قبل إجراء التحديثات.
10 - إجراء اختبار سنوى للكشف عن الاختراقات أو المخاطر الأمنية.
11 - استخدام معدات وأجهزة ونظم وبرمجيات الجدران النارية (NGFW-UTM-Firewalls) لحماية الشبكات والنظم.$m227$,'b600f08511ff8d4e342bcf596c404a00'),
(3,0,$m227$المادة 3$m227$,$m227$يلتزم مقدمو خدمات تقنية المعلومات والاتصالات التى تمتلك أو تدير أو تشغل البنية التحتية المعلوماتية الحرجة المخاطبين بأحكام هذا القانون، باتخاذ الإجراءات التقنية والتنظيمية التالية تنفيذا للبندين (2 و3) من الفقرة أولا من المادة رقم (2) من القانون:
1 - إعداد سياسة أمن معلومات واعتمادها من الإدارة العليا للبنية التحتية المعلوماتية الحرجة وضمان مراجعتها كل عام لضمان استمرار ملائمة وكفاية وفاعلية تلك السياسة.
على أن تتضمن تلك السياسة متطلبات الأجهزة والجهات الرقابية والتنظيمية المختصة بالبنية التحتية المعلوماتية الحرجة، والمتطلبات القانونية، والمتطلبات الخاصة بالموارد البشرية.
2 - ضمان التأكد من الامتثال لما ورد بهذا القانون ولائحته والقرارات التنفيذية ذات الصلة من التزامات تقنية أو تنظيمية.
3 - تشفير البيانات والمعلومات بما يحافظ على سريتها، وعدم اختراقها باستخدام نظام تشفير قياسى متماثل أو غير متماثل لا يقل تأمينه عن Advanced Encryption Standard (AES-256) بمفتاح شفرة لا يقل عن (256 بت) يتم توليده باستخدام نظام عشوائى آمن.
واستخدام نظام إدارة مفاتيح تشفير قياسى للحفاظ على سريتها ودورة حياتها ومستويات استخدامها فى التطبيقات المختلفة.
4 - استخدام شهادات تصديق إلكترونى صادرة من جهة من جهات إصدار شهادات التوقيع الإلكترونى المعترف بها فى جمهورية مصر العربية وبضوابط قانون تنظيم التوقيع الإلكترونى ولائحته التنفيذية، وذلك لكافة المستخدمين لأنظمة المعلومات الخاصة بالبنية المعلوماتية التحتية الحرجة.
5 - منع الوصول المادى لغير المخول أو المصرح لهم الدخول أو الوصول لمقار وأجهزة ومعدات أنظمة البنية التحتية المعلوماتية الحرجة.
6 - استخدام ضوابط نفاذ قوية Strong Authentication وفعالة من خلال فئتين أو أكثر من فئات التوثق Multi-factor Authentication وبحسب مستوى المخاطر، بما يضمن تحديد المسئولية وعدم الإنكار.
7 - توثيق إجراءات التنصيب والتشغيل الخاصة بنظم البنية التحتية المعلوماتية الحرجة وإتاحتها للمستخدمين المخول لهم ذلك عند حاجتهم إليها، وإلزام الموردين بتزويد الجهة بكامل الوثائق الخاصة بالإجراءات التشغيلية.
8 - ضمان تنفيذ وتشغيل وصيانة أنظمة البنية التحتية المعلوماتية الحرجة وإلزام الأطراف المتعاقد معها بإبرام اتفاقيات تحدد مستوى تقديم الخدمة مع الجهة.
9 - تنصيب واستخدام نظم وبرامج ومعدات المكافحة والحماية من البرمجيات والهجمات الخبيثة، والكشف عنها والتأكد من صلاحيتها وتحديثها.
10 - إجراء التحديثات الخاصة بالنظم والبرامج والتطبيقات بشكل دورى. مع الأخذ فى الاعتبار ضوابط التعامل مع إجراء التحديثات على أنظمة التحكم الصناعى مع عدم اتصالها المباشر بشبكة الإنترنت، وإتمام الاختبارات اللازمة قبل إجراء التحديثات.
11 - إجراء مسح سنوى لأنظمة التحكم الصناعى للكشف عن الثغرات ونقاط الضعف واتخاذ الإجراءات اللازمة للتعامل معها.
12 - إجراء اختبار سنوى للكشف عن الاختراقات أو المخاطر الأمنية وتثبيت أجهزة المنع والكشف عن الاختراقات.
13 - اتخاذ الإجراءات الملائمة للتعامل مع الثغرات الفنية للأجهزة وللنظم والبرامج والتطبيقات عند العلم بها.
14 - إجراء عمليات أخذ نسخ احتياطية شهرية للبيانات والمعلومات، والاحتفاظ بها وتخزينها مشفرة فى موقع آخر.
15 - استخدام معدات وأجهزة ونظم وبرمجيات الجدران النارية (NGFW-UTM-Firewalls) لحماية الشبكات والنظم.
16 - استخدام بروتوكولات آمنة، مثل بروتوكول نقل النص التشعبى المؤمن HTTPS.
17 - إعداد قائمة بالأجهزة والمعدات وأرقامها المميزة والمسلسلة وطرازاتها وكذا بيان بالنظم والبرامج والتطبيقات وقواعد البيانات المستخدمة ومواصفاتها.
18 - تحديد مسئوليات الإدارة العليا ومسئولى تكنولوجيا المعلومات وأمن المعلومات بشكل واضح وصلاحيات وسلطات وواجبات والتزامات كل منهم، مع ضرورة اتساق ذلك مع ما تقوم به إدارات الموارد البشرية وشئون العاملين من إعداد للهياكل، والتوصيف الوظيفى، والأنشطة التدريبية وغيرها من أنشطة وعمليات تلك الإدارات.
19 - إبلاغ المركز الوطنى للاستعداد لطوارئ الحاسب والشبكات بالجهاز عن أى حوادث أو اختراقات فور العلم بحدوثها.
20 - وضع خطة استمرارية العمل والبدائل المقترحة فى حال حدوث أى مخاطر أو أزمات تتعلق بتقديم الخدمة أو انقطاعها، والقدرة على استعادة الخدمة والعمل فى حال الكوارث، واختبار الخطة دوريا.$m227$,'13d1078493084ef4b6c9d459be3aa2a9'),
(4,0,$m227$المادة 4$m227$,$m227$ينشأ بالجهاز سجلان لقيد الخبراء، يقيد بأولهما الفنيون والتقنيون العاملون بالجهاز، ويقيد بالآخر الخبراء من الفنيين والتقنيين من غير العاملين به.
ويتم القيد فى السجل الأول الخاص بالعاملين بالجهاز بناء على القواعد والشروط والإجراءات الآتية:
1 - أن يكون حاصلا على مؤهل علمى أو فنى أو تقنى يتناسب ومجال الخبرة.
2 - أن يكون قد أمضى عام على الأقل فى عمله بالجهاز.
3 - أن يجتاز الاختبارات الفنية التى يجريها الجهاز للمتقدم.$m227$,'513208d2ecd003bdbea94f8adc4959dd'),
(5,0,$m227$المادة 5$m227$,$m227$يقيد الخبراء من الفنيين والتقنيين من غير العاملين بالجهاز بالسجل الثانى للخبراء طبقا للقواعد والشروط الآتية:
1 - أن يكون مصريا متمتعا بالأهلية المدنية الكاملة.
ويجوز قيد الأجنبى على أن يتعهد كتابة بخضوعه للقوانين المصرية.
2 - أن يكون محمود السيرة حسن السمعة.
3 - ألا يكون قد سبق الحكم عليه بحكم نهائى بالإدانة فى جريمة مخلة بالشرف.
4 - أن يكون لديه سيرة ذاتية تتضمن خبرة عملية مناسبة.
5 - موافقة الجهات المعنية من جهات الأمن القومى على القيد بالسجل.
ويترتب على تخلف أى شرط من الشروط السابقة الشطب من السجل بقرار من الجهاز.$m227$,'18d5e074321cba17655ce7389c698bb1'),
(6,0,$m227$المادة 6$m227$,$m227$يقوم الخبراء وفقا للمادتين رقمى (1)، (10) من القانون بتنفيذ المهام الفنية والتقنية التى يتم تكليفهم بها من جهات التحقيق أو الجهات القضائية المختصة أو من الجهات المعنية بمكافحة جرائم تقنية المعلومات بشأن الجرائم موضوع هذا القانون.$m227$,'212a137a06c7210abbf157af89055080'),
(7,0,$m227$المادة 7$m227$,$m227$يراعى الجهاز الحفاظ على سرية البيانات الواردة بسجلات قيد الخبراء وعدم الإفصاح عنها إلا بموجب أمر قضائى.$m227$,'9c9f4d025e12c6f71503202d1c48768f'),
(8,0,$m227$المادة 8$m227$,$m227$يتعين على من يرغب فى قيد اسمه فى السجل الثانى للخبراء أن يتقدم للرئيس التنفيذى للجهاز بطلب كتابى بذلك موضحا فيه التخصص الذى يرغب العمل فيه كخبير، وأن يرفق بالطلب صور الشهادات والمستندات المؤيدة لطلبه.
ويمكن للجهاز أن يطلب منه خلال ثلاثون يوما من تاريخ تقديم الطلب معلومات إضافية قبل الفصل فى الطلب، ويعتبر عدم الرد على الطلب لمدة ستين يوما من تاريخ تقديمه رفضا له.
وفى حال رفض الجهاز الطلب، يحق للمتقدم التظلم بالإجراءات المقررة قانونا.$m227$,'68320b6799d7e7ddb71202ef8b3da5a5'),
(9,0,$m227$المادة 9$m227$,$m227$تحوز الأدلة الرقمية ذات القيمة والحجية للأدلة الجنائية المادية فى الإثبات الجنائى إذا توافرت فيها الشروط والضوابط الآتية:
1 - أن تتم عملية جمع أو الحصول أو استخراج أو استنباط الأدلة الرقمية محل الواقعة باستخدام التقنيات التى تضمن عدم تغيير أو تحديث أو محو أو تحريف للكتابة أو البيانات والمعلومات، أو أى تغيير أو تحديث أو إتلاف للأجهزة أو المعدات أو البيانات والمعلومات، أو أنظمة المعلومات أو البرامج أو الدعامات الالكترونية وغيرها.
ومنها على الأخص تقنية Digital Images Hash، Write Blocker وغيرها من التقنيات المماثلة.
2 - أن تكون الأدلة الرقمية ذات صلة بالواقعة وفى إطار الموضوع المطلوب إثباته أو نفيه، وفقا لنطاق قرار جهة التحقيق أو المحكمة المختصة.
3 - أن يتم جمع الدليل الرقمى واستخراجه وحفظه وتحريزه بمعرفة مأمورى الضبط القضائى المخول لهم التعامل فى هذه النوعية من الأدلة، أو الخبراء أو المتخصصين المنتدبين من جهات التحقيق أو المحاكمة، على أن يبين فى محاضر الضبط، أو التقارير الفنية على نوع ومواصفات البرامج والأدوات والأجهزة والمعدات التى تم استخدامها، مع توثيق كود وخوارزم Hash الناتج عن استخراج نسخ مماثلة ومطابقة للأصل من الدليل الرقمى بمحضر الضبط أو تقرير الفحص الفنى، مع ضمان استمرار الحفاظ على الأصل دون عبث به.
4 - فى حالة تعذر فحص نسخة الدليل الرقمى وعدم إمكانية التحفظ على الأجهزة محل الفحص لأى سبب يتم فحص الأصل ويثبت ذلك كله فى محضر الضبط أو تقرير الفحص والتحليل.
5 - أن يتم توثيق الأدلة الرقمية بمحضر إجراءات من قبل المختص قبل عمليات الفحص والتحليل له وكذا توثيق مكان ضبطه ومكان حفظه ومكان التعامل معه ومواصفاته.$m227$,'f76dec5aeffe953f4d64959184cc45ac'),
(10,0,$m227$المادة 10$m227$,$m227$يتم توصيف وتوثيق الدليل الرقمى من خلال طباعة نسخ من الملفات المخزن عليها أو تصويرها بأى وسيلة مرئية أو رقمية، واعتمادها من الأشخاص القائمين على جمع أو استخراج أو الحصول أو التحليل للأدلة الرقمية، مع تدوين البيانات التالية على كل منها:
1 - تاريخ ووقت الطباعة والتصوير.
2 - اسم وتوقيع الشخص الذى قام بالطباعة والتصوير.
3 - اسم أو نوع نظام التشغيل ورقم الإصدار الخاص به.
4 - اسم البرنامج ونوع الإصدار أو الأوامر المستعملة لإعداد النسخ.
5 - البيانات والمعلومات الخاصة بمحتوى الدليل المضبوط.
6 - بيانات الأجهزة والمعدات والبرامج والأدوات المستخدمة.$m227$,'fd01096b5f87d72ed66dc98ca1c291fa'),
(11,0,$m227$المادة 11$m227$,$m227$يلتزم كل مسئول عن إدارة موقع أو حساب خاص أو بريد إلكترونى أو نظام معلوماتى سواء كان شخصا طبيعيا أو اعتباريا وفقا للمادة رقم (29) من القانون، باتخاذ التدابير والاحتياطات التأمينية الفنية اللازمة وفقا للالتزامات الواردة فى المادة رقم (2) من هذه اللائحة بالنسبة لمديرى مواقع مقدمى خدمات تقنية المعلومات.
كما يلتزم مديرو مواقع مقدمى خدمات تقنية المعلومات والاتصالات التى تمتلك أو تدير أو تشغل البنية التحتية المعلوماتية الحرجة بالالتزامات الواردة فى المادة رقم (3) من هذه اللائحة.
ويلتزم الممثل القانونى ومسئول الإدارة الفعلية لمقدمى الخدمة بإثبات توفيره الامكانيات التى تمكن مديرو المواقع من اتخاذ التدابير والاحتياطات التأمينية اللازمة لقيامه بعمله.
وفى جميع الأحوال يلتزم الممثل القانونى ومسئول الإدارة الفعلية ومدير الموقع لدى أى مقدم خدمة بإتاحة مفاتيح التشفير الخاصة به للمحكمة المختصة أو لجهات التحقيق المختصة فى حال وجود تحقيق فى إحدى الشكاوى أو المحاضر أو الدعاوى عند طلبها رسميا من تلك الجهات.$m227$,'f4f52826460306443a0c813b14acb25a'),
(12,0,$m227$المادة 12$m227$,$m227$يشترط لاعتماد الجهاز إقرار المجنى عليه بالصلح طبقا للمادة رقم (42) من القانون، فى الجرائم المنصوص عليها فى المواد (14، 17، 18، 23) استيفاء وتقديم ما يلى:
1 - شهادة صادرة من النيابة أو المحكمة المختصة بحسب الأحوال بالقيد والوصف للجريمة محل الصلح.
2 - صورة طبق الأصل من المحضر أو الوثيقة التى أثبت فيها الصلح بين المتهم والمجنى أو وكيله الخاص أو خلفه العام أمام النيابة أو المحكمة المختصة والمتضمنة إقرار المجنى عليه بهذا الصلح.
3 - شهادة صادرة من النيابة المختصة تفيد عدم صدور حكم نهائى فى الدعوى الجنائية.
4 - طلب باسم الرئيس التنفيذى للجهاز لاعتماد المحضر أو الوثيقة المتضمنة إقرار المجنى عليه بالصلح يقدم من المتهم أو من وكيله أو من خلفه العام.$m227$,'42cbbd95fc119e42e897110eb4d8835c'),
(13,0,$m227$المادة 13$m227$,$m227$يكون تصالح المتهم طبقا للمادة رقم (42) من القانون، فى الجرائم المنصوص عليها بالمادتين (29، 35) من القانون من خلال الجهاز باستيفاء وتقديم ما يلى:
شهادة صادرة من النيابة أو المحكمة المختصة بحسب الأحوال بالقيد والوصف للجريمة موضوع التصالح.
شهادة صادرة من النيابة المختصة تفيد عدم صدور حكم نهائى فى موضوع الجريمة محل طلب التصالح.
أن يقدم المتهم الراغب فى التصالح أو وكيله قبل رفع الدعوى الجنائية الإيصال الدال على سداده مبلغا يعادل ضعف الحد الأقصى للغرامة المقررة للجريمة.
أن يقدم المتهم الراغب فى التصالح أو وكيله بعد رفع الدعوى الجنائية الإيصال الدال على سداده ثلثى الحد الأقصى للغرامة المقررة للجريمة أو قيمة الحد الأدنى للغرامة أيهما أكثر قبل صدور حكم نهائى فى الموضوع.$m227$,'1bf34d05db21b1b1fcaf9620e6e04595');

INSERT INTO m227_ver VALUES
(0,0,1,$m227$قرار مجلس الوزراء رقم 1699 لسنة 2020 بتاريخ 27/08/2020 يعمل بأحكام اللائحة التنفيذية المرافقة فى شأن قانون مكافحة جرائم تقنية المعلومات المشار إليه.$m227$,'38ec81e60134b50a4da7150b9b843d8b',DATE '2020-08-27',NULL,'active',NULL,NULL,NULL),
(1,-1,1,$m227$يعمل بأحكام اللائحة التنفيذية المرافقة فى شأن قانون مكافحة جرائم تقنية المعلومات المشار إليه.$m227$,'4734ccb322444a1d04457a0cd86a288f',DATE '2020-08-27',NULL,'active',NULL,NULL,NULL),
(2,-1,1,$m227$ينشر هذا القرار فى الجريدة الرسمية، ويعمل به من اليوم التالى لتاريخ نشره.
صدر برئاسة مجلس الوزراء فى 8 المحرم سنة 1442 ه (الموافق 27 أغسطس سنة 2020 م).
رئيس مجلس الوزراء دكتور /مصطفى كمال مدبولى$m227$,'2532a56fde2d1261b07a2f771e5e56ac',DATE '2020-08-27',NULL,'active',NULL,NULL,NULL),
(1,0,1,$m227$فى تطبيق أحكام هذه اللائحة يقصد بالكلمات والعبارات التالية المعنى المبين قرين كل منها:
الجهاز: الجهاز القومى لتنظيم الاتصالات.
التشفير: Encryption منظومة تقنية حسابية تستخدم مفاتيح خاصة لمعالجة وتحويل البيانات والمعلومات المقروءة إلكترونيا بحيث تمنع استخلاص هذه البيانات والمعلومات إلا عن طريق استخدام مفتاح أو مفاتيح فك الشفرة.
مفتاح التشفير: Encryption Key أرقام أو رموز أو حروف ذات طول محدد تستخدم فى عمليات التشفير وفك التشفير.
ويستخدم نفس المفتاح فى التشفير وفك التشفير ويسمى التشفير المتماثل، ويجب الحفاظ على سرية المفتاح.
ويستخدم زوج من المفاتيح مترابطين بعلاقة رياضية بحيث يستخدم أحدهما فى التشفير والآخر فى فك التشفير ويسمى التشفير غير المتماثل، ويجب الحفاظ على سرية أحد المفاتيح بينما يعلن عن الآخر بشروط ومعايير محددة.
البنية التحتية المعلوماتية الحرجة: Critical Information Infrastructure مجموعة أنظمة أو شبكات أو أصول معلوماتية أساسية يؤدى الكشف عن تفصيلاتها تعطيلها أو تغيير طريقة عملها بطريقة غير مشروعة، أو الدخول غير المصرح به عليها، أو الدخول أو الوصول بشكل غير قانونى للبيانات والمعلومات التى تحفظها أو تعالجها، أو يؤدى القيام بأى فعل غير مشروع آخر بها إلى التأثير على توافر خدمات الدولة ومرافقها الأساسية أو خسائر اقتصادية أو اجتماعية كبيرة على المستوى الوطنى.
ويعد من البنية التحتية المعلوماتية الحرجة على الأخص ما يستخدم فى الطاقة الكهربائية، الغاز الطبيعى والبترول، الاتصالات، والجهات المالية والبنوك، والصناعات المختلفة، والنقل والمواصلات والطيران المدنى، والتعليم والبحث العلمى، والبث الإذاعى والتليفزيونى، ومحطات مياه الشرب والصرف الصحى والموارد المائية، والصحة، الخدمات الحكومية وخدمات الإغاثة وخدمات الطوارئ، وغيرها من مرافق المعلومات والاتصالات التى قد تؤثر على الأمن القومى أو الاقتصاد القومى والمصلحة العامة وما فى حكمها.
نظام التحكم الصناعى: حاسب أو مجموعة حواسب متصلة ببعضها البعض، وبالمعدات المتحكم بها وأدوات الاتصال المتبادل بينهم رقمية Digital أو تناظرية، Analog أو غيرها بما فى ذلك الحساسات والمنفذات Actuator لتشغيل هذه المعدات والتحكم بها منطقيا طبقا للصناعة المعنية، أو الأعمال المطلوبة فى مكان واحد أو موزعة فى أماكن متقاربة أو موزعة جغرافيا مع اتصال النظام بالإنترنت أو بغيره من الأنظمة المماثلة أو غير المماثلة أو استقلاله وعدم اتصاله بما عداه مع تراكم مستوى التحكم أو عدم تراكمه.
نقاط الضعف: Vulnerabilities خلل أو ثغرة فى نظام تشغيل أو تطبيقات أو شبكات المعلومات أو العمليات أو السياسات الخاصة بتأمين المعلومات أو فى بيئة تقنية المعلومات أو الاتصالات والتى يمكن استغلالها فى عمليات الاختراق أو الهجوم أو الاتلاف أو التجسس أو أى عمل غير مشروع.$m227$,'4635119cde09d02a3667b22cb3909f41',DATE '2020-08-27',NULL,'active',NULL,NULL,NULL),
(2,0,1,$m227$يلتزم مقدمو خدمات تقنيات المعلومات باتخاذ الإجراءات التقنية والتنظيمية التالية تنفيذا للبندين (2 و3) من الفقرة أولا من المادة رقم (2) من القانون:
1 - تشفير البيانات والمعلومات بما يحافظ على سريتها، وعدم اختراقها باستخدام نظام تشفير قياسى متماثل أو غير متماثل لا يقل فى تأمينه عن (ASE-128) Advanced Encryption Standard بمفتاح شفرة لا يقل عن (128 بت)، مع مسئوليته بالحفاظ على سرية وأمان مفتاح التشفير.
2 - تنصيب واستخدام نظم وبرامج ومعدات مكافحة البرمجيات والهجمات الخبيثة والتأكد من صلاحيتها وتحديثها.
3 - استخدام بروتوكولات آمنة، مثل بروتوكول نقل النص التشعبى المؤمن HTTPS.
4 - وضع صلاحيات بالشبكات والملفات وقواعد البيانات وتحديد المسئولين، لضمان حماية الوصول المنطقى Logical Access إلى الأصول المعلوماتية والتقنية لمنع الوصول غير المصرح به.
5 - إعداد قائمة بالأجهزة والمعدات وأرقامها المميزة والمسلسلة وطرازاتها وكذا بيان بالنظم والبرامج والتطبيقات وقواعد البيانات المستخدمة ومواصفاتها.
6 - تطبيق أفضل الممارسات والضوابط عند اختيار مواصفات كلمات السر أو المرور وفقا للملحق رقم (1) المرفق باللائحة التنفيذية.
7 - توثيق إجراءات التنصيب والتشغيل الخاصة بالأنظمة.
8 - ضمان تنفيذ وتشغيل وصيانة الأنظمة وإلزام الأطراف المتعاقد معها بإبرام اتفاقيات تحدد مستوى تقديم الخدمة مع الجهة وحدود مسئولية كل جهة.
9 - إجراء التحديثات الخاصة بالنظم والبرامج والتطبيقات بشكل دورى وإتمام الاختبارات اللازمة قبل إجراء التحديثات.
10 - إجراء اختبار سنوى للكشف عن الاختراقات أو المخاطر الأمنية.
11 - استخدام معدات وأجهزة ونظم وبرمجيات الجدران النارية (NGFW-UTM-Firewalls) لحماية الشبكات والنظم.$m227$,'b600f08511ff8d4e342bcf596c404a00',DATE '2020-08-27',NULL,'active',NULL,NULL,$m227$البند 6 يحيل إلى الملحق رقم (1) المرفق باللائحة (مواصفات كلمات السر) وهو غير وارد فى الملف المصدر ولم يُرفع.$m227$),
(3,0,1,$m227$يلتزم مقدمو خدمات تقنية المعلومات والاتصالات التى تمتلك أو تدير أو تشغل البنية التحتية المعلوماتية الحرجة المخاطبين بأحكام هذا القانون، باتخاذ الإجراءات التقنية والتنظيمية التالية تنفيذا للبندين (2 و3) من الفقرة أولا من المادة رقم (2) من القانون:
1 - إعداد سياسة أمن معلومات واعتمادها من الإدارة العليا للبنية التحتية المعلوماتية الحرجة وضمان مراجعتها كل عام لضمان استمرار ملائمة وكفاية وفاعلية تلك السياسة.
على أن تتضمن تلك السياسة متطلبات الأجهزة والجهات الرقابية والتنظيمية المختصة بالبنية التحتية المعلوماتية الحرجة، والمتطلبات القانونية، والمتطلبات الخاصة بالموارد البشرية.
2 - ضمان التأكد من الامتثال لما ورد بهذا القانون ولائحته والقرارات التنفيذية ذات الصلة من التزامات تقنية أو تنظيمية.
3 - تشفير البيانات والمعلومات بما يحافظ على سريتها، وعدم اختراقها باستخدام نظام تشفير قياسى متماثل أو غير متماثل لا يقل تأمينه عن Advanced Encryption Standard (AES-256) بمفتاح شفرة لا يقل عن (256 بت) يتم توليده باستخدام نظام عشوائى آمن.
واستخدام نظام إدارة مفاتيح تشفير قياسى للحفاظ على سريتها ودورة حياتها ومستويات استخدامها فى التطبيقات المختلفة.
4 - استخدام شهادات تصديق إلكترونى صادرة من جهة من جهات إصدار شهادات التوقيع الإلكترونى المعترف بها فى جمهورية مصر العربية وبضوابط قانون تنظيم التوقيع الإلكترونى ولائحته التنفيذية، وذلك لكافة المستخدمين لأنظمة المعلومات الخاصة بالبنية المعلوماتية التحتية الحرجة.
5 - منع الوصول المادى لغير المخول أو المصرح لهم الدخول أو الوصول لمقار وأجهزة ومعدات أنظمة البنية التحتية المعلوماتية الحرجة.
6 - استخدام ضوابط نفاذ قوية Strong Authentication وفعالة من خلال فئتين أو أكثر من فئات التوثق Multi-factor Authentication وبحسب مستوى المخاطر، بما يضمن تحديد المسئولية وعدم الإنكار.
7 - توثيق إجراءات التنصيب والتشغيل الخاصة بنظم البنية التحتية المعلوماتية الحرجة وإتاحتها للمستخدمين المخول لهم ذلك عند حاجتهم إليها، وإلزام الموردين بتزويد الجهة بكامل الوثائق الخاصة بالإجراءات التشغيلية.
8 - ضمان تنفيذ وتشغيل وصيانة أنظمة البنية التحتية المعلوماتية الحرجة وإلزام الأطراف المتعاقد معها بإبرام اتفاقيات تحدد مستوى تقديم الخدمة مع الجهة.
9 - تنصيب واستخدام نظم وبرامج ومعدات المكافحة والحماية من البرمجيات والهجمات الخبيثة، والكشف عنها والتأكد من صلاحيتها وتحديثها.
10 - إجراء التحديثات الخاصة بالنظم والبرامج والتطبيقات بشكل دورى. مع الأخذ فى الاعتبار ضوابط التعامل مع إجراء التحديثات على أنظمة التحكم الصناعى مع عدم اتصالها المباشر بشبكة الإنترنت، وإتمام الاختبارات اللازمة قبل إجراء التحديثات.
11 - إجراء مسح سنوى لأنظمة التحكم الصناعى للكشف عن الثغرات ونقاط الضعف واتخاذ الإجراءات اللازمة للتعامل معها.
12 - إجراء اختبار سنوى للكشف عن الاختراقات أو المخاطر الأمنية وتثبيت أجهزة المنع والكشف عن الاختراقات.
13 - اتخاذ الإجراءات الملائمة للتعامل مع الثغرات الفنية للأجهزة وللنظم والبرامج والتطبيقات عند العلم بها.
14 - إجراء عمليات أخذ نسخ احتياطية شهرية للبيانات والمعلومات، والاحتفاظ بها وتخزينها مشفرة فى موقع آخر.
15 - استخدام معدات وأجهزة ونظم وبرمجيات الجدران النارية (NGFW-UTM-Firewalls) لحماية الشبكات والنظم.
16 - استخدام بروتوكولات آمنة، مثل بروتوكول نقل النص التشعبى المؤمن HTTPS.
17 - إعداد قائمة بالأجهزة والمعدات وأرقامها المميزة والمسلسلة وطرازاتها وكذا بيان بالنظم والبرامج والتطبيقات وقواعد البيانات المستخدمة ومواصفاتها.
18 - تحديد مسئوليات الإدارة العليا ومسئولى تكنولوجيا المعلومات وأمن المعلومات بشكل واضح وصلاحيات وسلطات وواجبات والتزامات كل منهم، مع ضرورة اتساق ذلك مع ما تقوم به إدارات الموارد البشرية وشئون العاملين من إعداد للهياكل، والتوصيف الوظيفى، والأنشطة التدريبية وغيرها من أنشطة وعمليات تلك الإدارات.
19 - إبلاغ المركز الوطنى للاستعداد لطوارئ الحاسب والشبكات بالجهاز عن أى حوادث أو اختراقات فور العلم بحدوثها.
20 - وضع خطة استمرارية العمل والبدائل المقترحة فى حال حدوث أى مخاطر أو أزمات تتعلق بتقديم الخدمة أو انقطاعها، والقدرة على استعادة الخدمة والعمل فى حال الكوارث، واختبار الخطة دوريا.$m227$,'13d1078493084ef4b6c9d459be3aa2a9',DATE '2020-08-27',NULL,'active',NULL,NULL,NULL),
(4,0,1,$m227$ينشأ بالجهاز سجلان لقيد الخبراء، يقيد بأولهما الفنيون والتقنيون العاملون بالجهاز، ويقيد بالآخر الخبراء من الفنيين والتقنيين من غير العاملين به.
ويتم القيد فى السجل الأول الخاص بالعاملين بالجهاز بناء على القواعد والشروط والإجراءات الآتية:
1 - أن يكون حاصلا على مؤهل علمى أو فنى أو تقنى يتناسب ومجال الخبرة.
2 - أن يكون قد أمضى عام على الأقل فى عمله بالجهاز.
3 - أن يجتاز الاختبارات الفنية التى يجريها الجهاز للمتقدم.$m227$,'513208d2ecd003bdbea94f8adc4959dd',DATE '2020-08-27',NULL,'active',NULL,NULL,NULL),
(5,0,1,$m227$يقيد الخبراء من الفنيين والتقنيين من غير العاملين بالجهاز بالسجل الثانى للخبراء طبقا للقواعد والشروط الآتية:
1 - أن يكون مصريا متمتعا بالأهلية المدنية الكاملة.
ويجوز قيد الأجنبى على أن يتعهد كتابة بخضوعه للقوانين المصرية.
2 - أن يكون محمود السيرة حسن السمعة.
3 - ألا يكون قد سبق الحكم عليه بحكم نهائى بالإدانة فى جريمة مخلة بالشرف.
4 - أن يكون لديه سيرة ذاتية تتضمن خبرة عملية مناسبة.
5 - موافقة الجهات المعنية من جهات الأمن القومى على القيد بالسجل.
ويترتب على تخلف أى شرط من الشروط السابقة الشطب من السجل بقرار من الجهاز.$m227$,'18d5e074321cba17655ce7389c698bb1',DATE '2020-08-27',NULL,'active',NULL,NULL,NULL),
(6,0,1,$m227$يقوم الخبراء وفقا للمادتين رقمى (1)، (10) من القانون بتنفيذ المهام الفنية والتقنية التى يتم تكليفهم بها من جهات التحقيق أو الجهات القضائية المختصة أو من الجهات المعنية بمكافحة جرائم تقنية المعلومات بشأن الجرائم موضوع هذا القانون.$m227$,'212a137a06c7210abbf157af89055080',DATE '2020-08-27',NULL,'active',NULL,NULL,NULL),
(7,0,1,$m227$يراعى الجهاز الحفاظ على سرية البيانات الواردة بسجلات قيد الخبراء وعدم الإفصاح عنها إلا بموجب أمر قضائى.$m227$,'9c9f4d025e12c6f71503202d1c48768f',DATE '2020-08-27',NULL,'active',NULL,NULL,NULL),
(8,0,1,$m227$يتعين على من يرغب فى قيد اسمه فى السجل الثانى للخبراء أن يتقدم للرئيس التنفيذى للجهاز بطلب كتابى بذلك موضحا فيه التخصص الذى يرغب العمل فيه كخبير، وأن يرفق بالطلب صور الشهادات والمستندات المؤيدة لطلبه.
ويمكن للجهاز أن يطلب منه خلال ثلاثون يوما من تاريخ تقديم الطلب معلومات إضافية قبل الفصل فى الطلب، ويعتبر عدم الرد على الطلب لمدة ستين يوما من تاريخ تقديمه رفضا له.
وفى حال رفض الجهاز الطلب، يحق للمتقدم التظلم بالإجراءات المقررة قانونا.$m227$,'68320b6799d7e7ddb71202ef8b3da5a5',DATE '2020-08-27',NULL,'active',NULL,NULL,NULL),
(9,0,1,$m227$تحوز الأدلة الرقمية ذات القيمة والحجية للأدلة الجنائية المادية فى الإثبات الجنائى إذا توافرت فيها الشروط والضوابط الآتية:
1 - أن تتم عملية جمع أو الحصول أو استخراج أو استنباط الأدلة الرقمية محل الواقعة باستخدام التقنيات التى تضمن عدم تغيير أو تحديث أو محو أو تحريف للكتابة أو البيانات والمعلومات، أو أى تغيير أو تحديث أو إتلاف للأجهزة أو المعدات أو البيانات والمعلومات، أو أنظمة المعلومات أو البرامج أو الدعامات الالكترونية وغيرها.
ومنها على الأخص تقنية Digital Images Hash، Write Blocker وغيرها من التقنيات المماثلة.
2 - أن تكون الأدلة الرقمية ذات صلة بالواقعة وفى إطار الموضوع المطلوب إثباته أو نفيه، وفقا لنطاق قرار جهة التحقيق أو المحكمة المختصة.
3 - أن يتم جمع الدليل الرقمى واستخراجه وحفظه وتحريزه بمعرفة مأمورى الضبط القضائى المخول لهم التعامل فى هذه النوعية من الأدلة، أو الخبراء أو المتخصصين المنتدبين من جهات التحقيق أو المحاكمة، على أن يبين فى محاضر الضبط، أو التقارير الفنية على نوع ومواصفات البرامج والأدوات والأجهزة والمعدات التى تم استخدامها، مع توثيق كود وخوارزم Hash الناتج عن استخراج نسخ مماثلة ومطابقة للأصل من الدليل الرقمى بمحضر الضبط أو تقرير الفحص الفنى، مع ضمان استمرار الحفاظ على الأصل دون عبث به.
4 - فى حالة تعذر فحص نسخة الدليل الرقمى وعدم إمكانية التحفظ على الأجهزة محل الفحص لأى سبب يتم فحص الأصل ويثبت ذلك كله فى محضر الضبط أو تقرير الفحص والتحليل.
5 - أن يتم توثيق الأدلة الرقمية بمحضر إجراءات من قبل المختص قبل عمليات الفحص والتحليل له وكذا توثيق مكان ضبطه ومكان حفظه ومكان التعامل معه ومواصفاته.$m227$,'f76dec5aeffe953f4d64959184cc45ac',DATE '2020-08-27',NULL,'active',NULL,NULL,NULL),
(10,0,1,$m227$يتم توصيف وتوثيق الدليل الرقمى من خلال طباعة نسخ من الملفات المخزن عليها أو تصويرها بأى وسيلة مرئية أو رقمية، واعتمادها من الأشخاص القائمين على جمع أو استخراج أو الحصول أو التحليل للأدلة الرقمية، مع تدوين البيانات التالية على كل منها:
1 - تاريخ ووقت الطباعة والتصوير.
2 - اسم وتوقيع الشخص الذى قام بالطباعة والتصوير.
3 - اسم أو نوع نظام التشغيل ورقم الإصدار الخاص به.
4 - اسم البرنامج ونوع الإصدار أو الأوامر المستعملة لإعداد النسخ.
5 - البيانات والمعلومات الخاصة بمحتوى الدليل المضبوط.
6 - بيانات الأجهزة والمعدات والبرامج والأدوات المستخدمة.$m227$,'fd01096b5f87d72ed66dc98ca1c291fa',DATE '2020-08-27',NULL,'active',NULL,NULL,NULL),
(11,0,1,$m227$يلتزم كل مسئول عن إدارة موقع أو حساب خاص أو بريد إلكترونى أو نظام معلوماتى سواء كان شخصا طبيعيا أو اعتباريا وفقا للمادة رقم (29) من القانون، باتخاذ التدابير والاحتياطات التأمينية الفنية اللازمة وفقا للالتزامات الواردة فى المادة رقم (2) من هذه اللائحة بالنسبة لمديرى مواقع مقدمى خدمات تقنية المعلومات.
كما يلتزم مديرو مواقع مقدمى خدمات تقنية المعلومات والاتصالات التى تمتلك أو تدير أو تشغل البنية التحتية المعلوماتية الحرجة بالالتزامات الواردة فى المادة رقم (3) من هذه اللائحة.
ويلتزم الممثل القانونى ومسئول الإدارة الفعلية لمقدمى الخدمة بإثبات توفيره الامكانيات التى تمكن مديرو المواقع من اتخاذ التدابير والاحتياطات التأمينية اللازمة لقيامه بعمله.
وفى جميع الأحوال يلتزم الممثل القانونى ومسئول الإدارة الفعلية ومدير الموقع لدى أى مقدم خدمة بإتاحة مفاتيح التشفير الخاصة به للمحكمة المختصة أو لجهات التحقيق المختصة فى حال وجود تحقيق فى إحدى الشكاوى أو المحاضر أو الدعاوى عند طلبها رسميا من تلك الجهات.$m227$,'f4f52826460306443a0c813b14acb25a',DATE '2020-08-27',NULL,'active',NULL,NULL,NULL),
(12,0,1,$m227$يشترط لاعتماد الجهاز إقرار المجنى عليه بالصلح طبقا للمادة رقم (42) من القانون، فى الجرائم المنصوص عليها فى المواد (14، 17، 18، 23) استيفاء وتقديم ما يلى:
1 - شهادة صادرة من النيابة أو المحكمة المختصة بحسب الأحوال بالقيد والوصف للجريمة محل الصلح.
2 - صورة طبق الأصل من المحضر أو الوثيقة التى أثبت فيها الصلح بين المتهم والمجنى أو وكيله الخاص أو خلفه العام أمام النيابة أو المحكمة المختصة والمتضمنة إقرار المجنى عليه بهذا الصلح.
3 - شهادة صادرة من النيابة المختصة تفيد عدم صدور حكم نهائى فى الدعوى الجنائية.
4 - طلب باسم الرئيس التنفيذى للجهاز لاعتماد المحضر أو الوثيقة المتضمنة إقرار المجنى عليه بالصلح يقدم من المتهم أو من وكيله أو من خلفه العام.$m227$,'42cbbd95fc119e42e897110eb4d8835c',DATE '2020-08-27',NULL,'active',NULL,NULL,NULL),
(13,0,1,$m227$يكون تصالح المتهم طبقا للمادة رقم (42) من القانون، فى الجرائم المنصوص عليها بالمادتين (29، 35) من القانون من خلال الجهاز باستيفاء وتقديم ما يلى:
شهادة صادرة من النيابة أو المحكمة المختصة بحسب الأحوال بالقيد والوصف للجريمة موضوع التصالح.
شهادة صادرة من النيابة المختصة تفيد عدم صدور حكم نهائى فى موضوع الجريمة محل طلب التصالح.
أن يقدم المتهم الراغب فى التصالح أو وكيله قبل رفع الدعوى الجنائية الإيصال الدال على سداده مبلغا يعادل ضعف الحد الأقصى للغرامة المقررة للجريمة.
أن يقدم المتهم الراغب فى التصالح أو وكيله بعد رفع الدعوى الجنائية الإيصال الدال على سداده ثلثى الحد الأقصى للغرامة المقررة للجريمة أو قيمة الحد الأدنى للغرامة أيهما أكثر قبل صدور حكم نهائى فى الموضوع.$m227$,'1bf34d05db21b1b1fcaf9620e6e04595',DATE '2020-08-27',NULL,'active',NULL,NULL,NULL);

DO $m227$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_vcnt int;
BEGIN
  IF (SELECT count(*) FROM m227_art WHERE md5(body) <> body_md5) <> 0 OR (SELECT count(*) FROM m227_ver WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[227] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m227_art) <> 16 OR (SELECT sum(char_length(body)) FROM m227_art) <> 13842 OR (SELECT count(*) FROM m227_ver) <> 16 THEN
    RAISE EXCEPTION '[227] عدد الصفوف أو النسخ أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=1699 AND law_year=2020 AND kind='regulation';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%جرائم تقنية المعلومات%' THEN
    RAISE EXCEPTION '[227] يوجد مستند آخر برقم 1699 لسنة 2020 (%): لا يُدمج هذا النص فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (1699, 2020, $t227$اللائحة التنفيذية لقانون مكافحة جرائم تقنية المعلومات (القانون رقم 175 لسنة 2018) الصادرة بقرار رئيس مجلس الوزراء رقم 1699 لسنة 2020$t227$, $t227$اللائحة التنفيذية لقانون مكافحة جرائم تقنية المعلومات 1699/2020$t227$, 'other', 'in_force', NULL, DATE '2020-08-27', NULL, 'EG', 'regulation', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m227_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
  SELECT a.id, m.version_no, m.body, m.eff, m.eff_to, m.status, m.am_no, m.am_yr, m.note
    FROM articles a JOIN m227_ver m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m227_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 16 THEN
    RAISE EXCEPTION '[227] عدد صفوف النص % بدل 16', v_cnt;
  END IF;
  SELECT count(*) INTO v_vcnt FROM article_versions v JOIN articles a ON a.id=v.article_id WHERE a.law_id=v_law;
  IF v_vcnt <> 16 THEN
    RAISE EXCEPTION '[227] عدد نسخ النص % بدل 16', v_vcnt;
  END IF;
  RAISE NOTICE '[227] لائحة 1699/2020: جديد=%، صفوف مضافة=%، نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m227$;
